    public static function render(string $name, int $size = 20, string $class = ''): string
    {
        $path = self::PATHS[$name] ?? self::PATHS['activity'];
        $cls = $class !== '' ? ' class="' . htmlspecialchars($class, ENT_QUOTES) . '"' : '';
        return sprintf(
            '<svg%s width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>',
            $cls, $size, $size, $path
        );
    }
